import XCTest
@testable import KeyPocketCore

final class ProtocolTests: XCTestCase {
    func door(type: Int = 0) -> DoorKey {
        DoorKey(id: "test", keyID: type == 5 ? -1 : 123456, title: "Test door", project: "010203", license: type == 100 ? "000000" : "a1b2c3", floor: type == 100 ? "0" : (type == 5 ? "0000000000000041" : "7"), type: type, expires: 1800000000, enabled: true, remaining: 0, group: "owner_keys", projectName: "Synthetic")
    }
    // Golden outputs generated by compiling the recovered Java TEA and frame methods
    // against synthetic IDs and a fixed timestamp; see docs/ANALYSIS.md.
    func testChallengeMatchesJava() throws {
        let reply = try BLEProtocol.challenge(Data(Array(repeating: UInt8(0), count: 8) + Array(0...7) + [0, 0]))
        XCTAssertEqual(reply.token, [7,6,5,4,3,2,1,0])
        XCTAssertEqual(reply.response.hex, "55aa12c500000000f3ad2a90e32161a733fb")
        XCTAssertThrowsError(try BLEProtocol.challenge(Data(repeating: 0, count: 17)))
    }
    func testPayloadMatchesJavaForEachSupportedFamily() throws {
        let expected = [
            0: "863fc6355229333375f3eee25fe85e2d47b73096e19bc4c5fad26283173673c6c215291dafbeaf9d",
            3: "3ffe8c98ecc177ec75f3eee25fe85e2d876666100aeb487b04e0b01400a94c3cc215291dafbeaf9d",
            5: "3ffe8c98ecc177eccb1225c97c889c3a47b73096e19bc4c5e8ba126febb05d67c215291dafbeaf9d",
            6: "863fc6355229333375f3eee25fe85e2d47b73096e19bc4c5fad26283173673c6c215291dafbeaf9d",
            100: "b146d18fab487dd61667ae3a7c336464876666100aeb487bea67737cb1b23112c215291dafbeaf9d"
        ]
        for (type, payload) in expected {
            XCTAssertEqual(try BLEProtocol.payload(door: door(type: type), timestamp: 1700000000, token: [7,6,5,4,3,2,1,0]).hex, payload, "type \(type)")
        }
        XCTAssertEqual(try Data(BLEProtocol.plaintext(door: door(type: 100), timestamp: 1700000000)).hex, "01010101000102030000000040e2010000000000ffffffff8000000000f15365aa00000000000000")
    }
    func testAESMatchesJavaAndRoundTripsUnicode() throws {
        let plain = Data(#"{"mobile":"13800000000"}"#.utf8)
        XCTAssertEqual(try APIEnvelope.encrypt(plain), "zyMCyXpYIQ6ZloIijtOtsGneXusPUIIQ906QYWGYvIo=")
        let unicode = Data("门禁\n钥匙🔑".utf8)
        XCTAssertEqual(try APIEnvelope.decrypt(APIEnvelope.encrypt(unicode)), unicode)
        XCTAssertThrowsError(try APIEnvelope.decrypt("invalid"))
    }
    func testRejectExpiredDisabledInvalidAndVisitorKeys() throws {
        var key = door(); key.expires = 1700000000
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        key = door(); key.enabled = false
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        key = door(type: 1)
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        key = door(); key.project = "nothex"
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        key = door(); key.floor = "32"
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        key.floor = "0"
        XCTAssertThrowsError(try key.validate(now: 1700000000))
        XCTAssertThrowsError(try BLEProtocol.payload(door: door(), timestamp: 1700000000, token: []))
    }
    func testDiscoveryIsBoundToSelectedProjectAndLicense() {
        XCTAssertTrue(BLEProtocol.matches(name: "1010203a1b2c3A", door: door()))
        XCTAssertTrue(BLEProtocol.matches(name: "2010203ffffffA", door: door()))
        XCTAssertFalse(BLEProtocol.matches(name: "1010203111111A", door: door()))
        XCTAssertFalse(BLEProtocol.matches(name: "2999999a1b2c3A", door: door()))
        XCTAssertFalse(BLEProtocol.matches(name: "0123456123456A", door: door()))
    }
    func testParserUnderstandsJSONStringArraysAndGroupMasks() throws {
        let row: [String: Any] = ["id": "12", "type": 0, "end_time": "1800000000", "project_license": "010203", "license": "a1b2c3", "floor_station": "7", "project_name": "小区"]
        let encoded = String(data: try JSONSerialization.data(withJSONObject: [row]), encoding: .utf8)!
        let list = try KeyParser.parse(["owner_keys": encoded, "gate_keys": []])
        XCTAssertEqual(list.count, 1); XCTAssertEqual(list.first?.keyID, 12)
        var group = row
        group["type"] = 5; group["ids"] = ["41", "42"]; group["licenses"] = ["a1b2c3", "d4e5f6"]; group["floor_stations"] = ["01", "02"]
        let grouped = try KeyParser.parse(["owner_keys": [group]])
        XCTAssertEqual(grouped.count, 2); XCTAssertEqual(grouped[1].floor, "02")
        group["floor_stations"] = []
        XCTAssertThrowsError(try KeyParser.parse(["owner_keys": [group]]))
        XCTAssertThrowsError(try KeyParser.parse(["owner_keys": [row, row]]))
    }
}

private extension Data { var hex: String { map { String(format: "%02x", $0) }.joined() } }
